head.b:skin:
:root{--bg:#090c11;--panel:#121720;--panel2:#171d27;--line:#2b3442;--line2:#3a4657;--text:#f3f6fa;--muted:#99a5b3;--soft:#ccd4de;--blue:#8aa4ff;--green:#79d0ad;--amber:#d8b86d;--rose:#dc7f8a;--max:1440px;--r:11px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:linear-gradient(180deg,#0b0e13,#090c11 55%,#080a0e);color:var(--text);font-family:Arial,Helvetica,sans-serif;line-height:1.55}body:before{content:'';position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:linear-gradient(rgba(255,255,255,.024) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.02) 1px,transparent 1px);background-size:48px 48px}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto}.edge-shell{width:min(calc(100% - 32px),var(--max));margin:auto}.edge-topline{height:4px;background:linear-gradient(90deg,#8198ef 0 36%,#76c6a7 36% 64%,#cfb16a 64% 82%,#c67f8c 82%)}
.edge-head{position:sticky;top:0;z-index:60;background:rgba(10,13,18,.96);border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}.edge-headrow{min-height:72px;display:flex;align-items:center;gap:18px}.edge-brand{font-size:34px;font-weight:900;letter-spacing:-2px}.edge-brand span{color:var(--blue)}.edge-tag{font-size:10px;color:var(--muted);letter-spacing:1.5px;text-transform:uppercase;border-left:1px solid var(--line);padding-left:17px}.edge-search{margin-left:auto;display:flex;min-width:min(360px,34vw);border:1px solid var(--line2);border-radius:7px;background:#0f141c;overflow:hidden}.edge-search input{width:100%;border:0;outline:0;background:transparent;color:var(--text);padding:10px 12px}.edge-search button{border:0;border-left:1px solid var(--line);background:#171d26;color:#e4e9ef;font-weight:800;padding:10px 13px}.edge-nav{border-top:1px solid rgba(255,255,255,.035);overflow:auto}.edge-nav-inner{display:flex;min-width:max-content}.edge-nav a{padding:10px 12px;font-size:10px;font-weight:800;letter-spacing:.9px;text-transform:uppercase;color:#aeb8c4;border-bottom:2px solid transparent}.edge-nav a:hover{color:#fff;border-bottom-color:var(--blue)}
.edge-ticker{background:#11161d;border-bottom:1px solid var(--line)}.edge-ticker-inner{min-height:39px;display:flex;align-items:center;overflow:hidden}.ticker-label{flex:none;background:#e9eef5;color:#11161d;font-size:9px;font-weight:900;letter-spacing:1.2px;padding:5px 8px;border-radius:4px;margin-right:14px}.ticker-window{overflow:hidden;white-space:nowrap;flex:1}.ticker-track{display:inline-flex;gap:31px;animation:edgeTicker 62s linear infinite}.ticker-track:hover{animation-play-state:paused}.ticker-item{font-size:12px;color:#d5dce5;padding-left:16px;border-left:1px solid #3a4657}.ticker-item:first-child{padding-left:0;border-left:0}@keyframes edgeTicker{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.edge-home{padding:21px 0 48px}.edge-newsbar{display:flex;justify-content:space-between;align-items:end;margin-bottom:11px}.edge-kicker{font-size:10px;font-weight:900;letter-spacing:1.6px;text-transform:uppercase;color:var(--blue)}.edge-date{font-size:9px;color:var(--muted);letter-spacing:1px;text-transform:uppercase}.edge-hero{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(330px,.8fr);gap:11px;margin-bottom:21px}.hero-main,.hero-side{display:grid;gap:11px}.hero-side{grid-template-rows:1fr 1fr}.hero-card{position:relative;min-height:210px;overflow:hidden;border:1px solid var(--line);border-radius:var(--r);background:var(--panel);box-shadow:0 18px 50px rgba(0,0,0,.25)}.hero-main .hero-card{min-height:450px}.hero-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(.85) contrast(1.05)}.hero-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(6,8,12,.98),rgba(6,8,12,.76) 31%,rgba(6,8,12,.12) 74%)}.hero-copy{position:absolute;z-index:2;left:0;right:0;bottom:0;padding:23px}.hero-copy h2{font-size:clamp(28px,3.7vw,48px);line-height:1.04;letter-spacing:-1.5px;margin:8px 0 9px}.hero-side .hero-copy h2{font-size:clamp(18px,1.8vw,25px);letter-spacing:-.6px}.hero-meta{font-size:9px;color:#b7c0cb;letter-spacing:.8px;text-transform:uppercase}.hero-summary{color:#d2d9e2;font-size:13px;max-width:780px;margin:8px 0 0}.hero-side .hero-summary{display:none}.edge-chip{display:inline-block;border:1px solid rgba(138,164,255,.55);background:rgba(17,23,32,.8);color:#cad4ff;border-radius:4px;padding:4px 7px;font-size:8px;font-weight:900;letter-spacing:.9px;text-transform:uppercase}.edge-empty{display:flex;align-items:flex-end;min-height:200px;padding:20px;color:var(--muted)}
.edge-front{display:grid;grid-template-columns:minmax(0,1fr) 325px;gap:19px}.edge-section-head{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid var(--line2);padding-bottom:8px;margin:0 0 11px}.edge-section-head h2,.edge-section-head h3{margin:0;font-size:20px;letter-spacing:-.5px}.edge-section-head span{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.9px}.edge-latest-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.news-card{display:grid;grid-template-columns:165px minmax(0,1fr);min-height:166px;background:var(--panel);border:1px solid var(--line);border-radius:var(--r);overflow:hidden}.news-card:hover{border-color:#465264;background:#151b25}.news-media{min-height:166px;background:#10151d;overflow:hidden}.news-media img{width:100%;height:100%;min-height:166px;object-fit:cover;display:block}.news-copy{padding:13px;display:flex;flex-direction:column}.news-kicker{display:flex;align-items:center;gap:6px;font-size:8px;font-weight:900;text-transform:uppercase;letter-spacing:.8px;color:var(--green)}.news-card h3{font-size:17px;line-height:1.16;letter-spacing:-.4px;margin:6px 0}.news-card p{font-size:12px;line-height:1.42;color:#b9c2cd;margin:0 0 9px}.news-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto;font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px}.read-more{font-weight:900;color:#e1e7ee}.read-more:after{content:' →';color:var(--blue)}.mini-trust{display:inline-flex;align-items:center;gap:5px}.trust-dot{width:8px;height:8px;border-radius:50%;background:var(--trust)}.mini-trust em{font-style:normal;color:#abb5c1}
.edge-rail{display:flex;flex-direction:column;gap:11px}.edge-box{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:14px}.edge-box h3{margin:0 0 10px;font-size:11px;letter-spacing:1.05px;text-transform:uppercase}.edge-status{display:grid;grid-template-columns:1fr 1fr;gap:7px}.edge-status a,.edge-cats a{border:1px solid var(--line);border-radius:6px;padding:9px;font-size:10px;color:#bec7d2}.edge-status b{display:block;font-size:14px}.edge-status a:nth-child(1) b{color:var(--green)}.edge-status a:nth-child(2) b{color:var(--amber)}.edge-status a:nth-child(3) b{color:var(--blue)}.edge-status a:nth-child(4) b{color:var(--rose)}.edge-list{display:flex;flex-direction:column}.edge-list a{padding:9px 0;border-top:1px solid rgba(255,255,255,.055);font-size:12px;font-weight:800;line-height:1.28}.edge-list a:first-child{border-top:0}.edge-list small{display:block;margin-top:3px;color:var(--muted);font-weight:400}.edge-cats{display:grid;grid-template-columns:1fr 1fr;gap:7px}.edge-method{font-size:11px;color:#aeb7c2;line-height:1.5}.edge-method strong{color:#e8edf3}.edge-pulse{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.edge-pulse div{padding:9px 7px;border:1px solid var(--line);border-radius:6px;background:#10151c}.edge-pulse b{display:block;font-size:17px}.edge-pulse span{font-size:8px;color:var(--muted);text-transform:uppercase;letter-spacing:.7px}
.edge-desks{margin-top:24px}.edge-desk-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.edge-desk{border-top:2px solid #53647a;background:var(--panel);border-radius:0 0 var(--r) var(--r);padding:13px}.edge-desk:nth-child(2){border-top-color:#5e8d7c}.edge-desk:nth-child(3){border-top-color:#9c8656}.edge-desk:nth-child(4){border-top-color:#806f99}.edge-desk h3{margin:0 0 9px;font-size:14px}.desk-story{display:grid;grid-template-columns:82px 1fr;gap:9px;padding:8px 0;border-top:1px solid rgba(255,255,255,.055)}.desk-story:first-of-type{border-top:0}.desk-story img{width:82px;height:62px;object-fit:cover;border-radius:5px;background:#10151d}.desk-story b{display:block;font-size:12px;line-height:1.24}.desk-story p{font-size:10px;line-height:1.32;color:var(--muted);margin:4px 0 0}.desk-empty{font-size:11px;color:var(--muted)}
.edge-native{padding:27px 0 56px}.edge-native-grid{display:grid;grid-template-columns:minmax(0,1fr) 325px;gap:22px}.main .widget,.Blog{background:transparent!important}.post-outer,.post-outer-container{background:var(--panel)!important;border:1px solid var(--line)!important;border-radius:var(--r)!important;margin:0 0 17px!important;overflow:hidden}.post{padding:23px!important}.post-title,.post-title.entry-title{font-size:clamp(25px,3vw,38px)!important;line-height:1.1!important;letter-spacing:-1px!important;margin:0 0 10px!important}.post-title a:hover{color:#cbd5ff}.post-header,.post-header-line-1,.post-timestamp{color:var(--muted)!important;font-size:11px!important}.post-body{font-size:16px;color:#d8dee6}.post-body h2,.post-body h3{color:#f5f7fa}.post-body a{color:#b5c4ff;text-decoration:underline}.post-body blockquote{border-left:3px solid #6f819a;padding:8px 17px;margin:21px 0;background:#151b24;color:#cbd3dd}.post-labels a,.labels a{display:inline-block;margin:5px 5px 0 0;border:1px solid var(--line);border-radius:5px;padding:5px 8px;color:#bdc6d1;font-size:9px;text-transform:uppercase;letter-spacing:.6px}.post-labels a[href*='CONFIRMED']{color:var(--green)}.post-labels a[href*='DEVELOPING']{color:var(--amber)}.post-labels a[href*='EARLY']{color:var(--blue)}.post-labels a[href*='RUMOUR']{color:var(--rose)}
.edge-foot{border-top:1px solid var(--line);background:#0c1016;padding:29px 0 40px;color:var(--muted);font-size:11px}.edge-foot-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:23px}.edge-foot strong{color:#eef2f7;font-size:14px}.edge-foot a:hover{color:#fff}
@media(max-width:1100px){.edge-latest-grid{grid-template-columns:1fr}.edge-front{grid-template-columns:minmax(0,1fr) 300px}}@media(max-width:900px){.edge-tag{display:none}.edge-search{min-width:0;flex:1}.edge-hero{grid-template-columns:1fr}.hero-main .hero-card{min-height:380px}.hero-side{grid-template-columns:1fr 1fr;grid-template-rows:auto}.edge-front,.edge-native-grid{grid-template-columns:1fr}.edge-rail{display:grid;grid-template-columns:1fr 1fr}.edge-desk-grid{grid-template-columns:1fr 1fr}}@media(max-width:640px){.edge-shell{width:min(calc(100% - 20px),var(--max))}.edge-headrow{min-height:63px;gap:8px}.edge-brand{font-size:27px}.edge-search input{padding:9px}.edge-search button{padding:9px}.hero-main .hero-card{min-height:340px}.hero-side{grid-template-columns:1fr}.hero-side .hero-card{min-height:205px}.hero-copy{padding:18px}.hero-copy h2{font-size:28px}.edge-latest-grid,.edge-desk-grid{grid-template-columns:1fr}.news-card{grid-template-columns:118px minmax(0,1fr)}.news-media,.news-media img{min-height:158px}.news-card p{display:none}.edge-rail{display:flex}.edge-foot-grid{grid-template-columns:1fr}.post{padding:18px!important}}

body.script:
//
(function(){
var fallback='https://raw.githubusercontent.com/BoomForge/EdgeAI/main/assets/edgeai-newsroom-fallback.svg';
function esc(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML;}
function cleanTickerTitle(v){return String(v||'').replace(/^(?:&?#?8226;|&#x2022;|•)\s*/i,'').trim();}
function entries(j){return(j&&j.feed&&j.feed.entry)||[];}
function href(e){var a=e.link||[];for(var i=0;i<a.length;i++)if(a[i].rel==='alternate')return a[i].href;return'#';}
function raw(e){return(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';}
function thumb(e){var h=raw(e),m=h.match(/<figure[^>]*class=["'][^"']*edge-article-hero[^"']*["'][\s\S]*?<img[^>]+src=["']([^"']+)/i);if(!m)m=h.match(/<img[^>]+src=["']([^"']+)/i);if(m&&m[1])return m[1];if(e.media$thumbnail&&e.media$thumbnail.url)return e.media$thumbnail.url.replace(/\/s72-c\//,'/s1200/');return fallback;}
function plain(e,n){var d=document.createElement('div');d.innerHTML=raw(e);var kill=d.querySelectorAll('.edge-trust-card,.edge-article-hero');for(var i=0;i<kill.length;i++)kill[i].remove();var t=(d.textContent||'').replace(/\s+/g,' ').trim();return t.slice(0,n||180)+(t.length>(n||180)?'…':'');}
function when(e){var v=(e.published&&e.published.$t)||'';try{return new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric'});}catch(x){return'';}}
function cats(e){var c=e.category||[],a=[];for(var i=0;i<c.length;i++)a.push(c[i].term);return a;}
function trust(e){var s=raw(e),m=s.match(/data-trust-score=["'](\d+)["']/i),l=s.match(/data-trust-label=["']([^"']+)["']/i),txt=document.createElement('div');txt.innerHTML=s;var q=(txt.textContent||'').replace(/\s+/g,' '),tm=q.match(/Evidence Trust[^0-9]{0,80}(\d{1,3})/i),tl=q.match(/Evidence Trust[^A-Za-z]{0,20}[^ ]+\s+(Verified|Strong|Reasonable|Caution|Low confidence)/i),n=m?parseInt(m[1],10):(tm?parseInt(tm[1],10):0),label=l?l[1]:(tl?tl[1]:'Unrated');return{score:n,label:label,color:n>=90?'#79d0ad':n>=75?'#8aa4ff':n>=60?'#d8b86d':'#dc7f8a'};}
function hero(e,small){var im=thumb(e);return'<a class="hero-card" href="'+esc(href(e))+'"><img alt="" src="'+esc(im)+'" onerror="this.onerror=null;this.src=\''+fallback+'\';"/><div class="hero-copy"><span class="edge-chip">'+esc((cats(e)[0]||'Featured'))+'</span><h2>'+esc(e.title.$t)+'</h2><div class="hero-meta">'+esc(when(e))+'</div>'+(small?'':'<p class="hero-summary">'+esc(plain(e,210))+'</p>')+'</div></a>';}
function card(e){var t=trust(e),cs=cats(e);return'<article class="news-card"><a class="news-media" href="'+esc(href(e))+'"><img alt="" src="'+esc(thumb(e))+'" onerror="this.onerror=null;this.src=\''+fallback+'\';"/></a><div class="news-copy"><div class="news-kicker">'+esc(cs[0]||'Latest')+' · '+esc(when(e))+'</div><a href="'+esc(href(e))+'"><h3>'+esc(e.title.$t)+'</h3></a><p>'+esc(plain(e,145))+'</p><div class="news-foot"><span class="mini-trust" style="--trust:'+t.color+'"><span class="trust-dot"></span><em>'+esc(t.score?t.score+'/100 '+t.label:'Trust pending')+'</em></span><a class="read-more" href="'+esc(href(e))+'">Read More</a></div></div></article>';}
function deskStory(e){return'<a class="desk-story" href="'+esc(href(e))+'"><img alt="" src="'+esc(thumb(e))+'" onerror="this.onerror=null;this.src=\''+fallback+'\';"/><span><b>'+esc(e.title.$t)+'</b><p>'+esc(plain(e,82))+'</p></span></a>';}
window.edgeAIHero=function(j){var es=entries(j),h=document.getElementById('edgeai-hero');if(!h)return;if(!es.length&&!window.edgeAIFallback){window.edgeAIFallback=true;load('/feeds/posts/default?alt=json-in-script&max-results=3&callback=edgeAIHero');return;}if(!es.length)return;var a='<div class="hero-main">'+hero(es[0],false)+'</div><div class="hero-side">';for(var i=1;i<3;i++)a+=es[i]?hero(es[i],true):'<div class="hero-card edge-empty">More intelligence incoming.</div>';h.innerHTML=a+'</div>';};
window.edgeAILatest=function(j){var es=entries(j),t=document.getElementById('edgeai-latest');if(!t)return;var a='';for(var i=0;i<Math.min(es.length,8);i++)a+=card(es[i]);t.innerHTML=a||'<div class="edge-empty">No reports yet.</div>';};
window.edgeAITicker=function(j){var es=entries(j),t=document.getElementById('edgeai-ticker');if(!t||!es.length)return;var a='';for(var i=0;i<es.length;i++)a+='<a class="ticker-item" href="'+esc(href(es[i]))+'">'+esc(cleanTickerTitle(es[i].title.$t))+'</a>';t.innerHTML=a+a;};
window.edgeAITrending=function(j){var es=entries(j),nodes=document.querySelectorAll('#edgeai-trending'),a='';for(var i=0;i<Math.min(es.length,7);i++)a+='<a href="'+esc(href(es[i]))+'">'+esc(es[i].title.$t)+'<small>'+esc(when(es[i]))+'</small></a>';for(var n=0;n<nodes.length;n++)nodes[n].innerHTML=a||'<span class="edge-method">No stories yet.</span>';};
window.edgeAIDeskModels=function(j){desk('desk-models',entries(j));};window.edgeAIDeskTools=function(j){desk('desk-tools',entries(j));};window.edgeAIDeskResearch=function(j){desk('desk-research',entries(j));};window.edgeAIDeskOpen=function(j){desk('desk-open',entries(j));};
function desk(id,es){var t=document.getElementById(id);if(!t)return;var a='';for(var i=0;i<Math.min(es.length,3);i++)a+=deskStory(es[i]);t.innerHTML=a||'<span class="desk-empty">More reports incoming.</span>';}
function load(src){var s=document.createElement('script');s.src=src;document.body.appendChild(s);}
var d=document.getElementById('edgeai-date');if(d)d.textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});
load('/feeds/posts/default/-/Featured?alt=json-in-script&max-results=3&callback=edgeAIHero');load('/feeds/posts/default?alt=json-in-script&max-results=12&callback=edgeAILatest');load('/feeds/posts/default?alt=json-in-script&max-results=12&callback=edgeAITicker');load('/feeds/posts/default?alt=json-in-script&max-results=7&callback=edgeAITrending');load('/feeds/posts/default/-/Models?alt=json-in-script&max-results=3&callback=edgeAIDeskModels');load('/feeds/posts/default/-/Tools?alt=json-in-script&max-results=3&callback=edgeAIDeskTools');load('/feeds/posts/default/-/Research?alt=json-in-script&max-results=3&callback=edgeAIDeskResearch');load('/feeds/posts/default/-/Open%20Source?alt=json-in-script&max-results=3&callback=edgeAIDeskOpen');
})();
//
